Boolean dst_bus_err_save (void)           
{ 
  Boolean status = nvfs_wr (nvfs_dst_bus_error, &dst_bus_vars.err) == NVFS_OK ;

  #if DBG_DST_BUS == 1
    dst_bus_dbg_print ("\nDst Bus Err Save = ", &status , 1) ;
  #endif

  
  return status;  
}


